function mapScopeToPermission(scope: PantavionAppRouteScope): 'self' | 'tenant' | 'governor' | 'founder' {
  switch (scope) {
    case 'public':
      return 'self';
    case 'self':
      return 'self';
    case 'operator':
      return 'governor';
    case 'founder':
      return 'founder';
  }
}

