function mapAvailabilityToHealth(
  availability: PantavionProviderAdapterAvailability,
): PantavionProviderHealthStatus {
  switch (availability) {
    case 'ready':
      return 'healthy';
    case 'maintenance':
      return 'watch';
    case 'degraded':
      return 'degraded';
    case 'offline':
    case 'retired':
      return 'offline';
    default:
      return 'watch';
  }
}

