export function normalizeWaterSearchText(value: string | undefined | null) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[ς]/g, "σ")
    .replace(/[^a-z0-9α-ω\s-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

