function renderRecallBundle(
  bundle: PantavionContinuityRecallBundle,
): string {
  return [
    'PANTAVION CONTINUITY RECALL BUNDLE',
    `generatedAt=${bundle.generatedAt}`,
    `userId=${bundle.userId}`,
    `activeThreadId=${bundle.activeThreadId ?? ''}`,
