      return "assistant";
    case "research":
    case "browser-search":
      return "research";
    case "coding":
    case "app-building":
      return "builder";
    case "design":
    case "image":
    case "video":
    case "audio":
    case "writing":
    case "presentation":
      return "creator";
    case "notes-memory":
      return "memory";
    case "automation":
      return "automation";
    case "learning":
      return "learning";
    case "business":
    case "finance":
      return "business";
    case "data":
      return "data";
    case "security-defense":
      return "security";
    case "voice-translation":
      return "voice";
    case "identity-governance":
      return "provider-awareness";
    case "health-knowledge":
    case "productivity":
      return "assistant";
    default:
