      return {
        actionType,
        allowed: false,
        reason: 'Foreign source code copying is blocked by legal-safe doctrine.',
        riskTier: 'critical',
      };
    case 'use-leaked-internal-doc':
      return {
        actionType,
        allowed: false,
        reason: 'Leaked or private internal materials are blocked entirely.',
        riskTier: 'critical',
