  request: PantavionSecretAccessRequest,
): PantavionSecretAccessDecision {
  if (request.actorClass === 'client') {
    return {
      secretKey: request.secretKey,
      allowed: false,
      requiresRotation: false,
      reason: 'Secrets may never be exposed to client-side actors.',
    };
  }

